int main(){
double old[3]={0.5,1,0.5},rhs[3]={},solution[3]={};
double theta=0.2;
for(int i=0;i<3;i++){
    double left=i>0?old[i-1]:0,right=i<2?old[i+1]:0;
    rhs[i]=(1-theta)*old[i]+0.5*theta*(left+right);
}
double a=-theta/2,b=1+theta,c=-theta/2,modified[3]={},target[3]={};
modified[0]=c/b;target[0]=rhs[0]/b;
for(int i=1;i<3;i++){
    double denom=b-a*modified[i-1];
    modified[i]=i<2?c/denom:0;
    target[i]=(rhs[i]-a*target[i-1])/denom;
}
solution[2]=target[2];
for(int i=1;i>=0;i--)solution[i]=target[i]-modified[i]*solution[i+1];
for(double value:solution)cout<<value<<" ";cout<<"
";
return 0;
}

