#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
double wealth=100,mu=0.08,riskfree=0.02,sigma=0.2,dt=0.1;
double best=-1e100,bestWeight=0;
for(int i=0;i<=100;i++){
    double weight=i/100.0;
    double drift=riskfree+weight*(mu-riskfree);
    double up=wealth*(1+drift*dt+weight*sigma*sqrt(dt));
    double down=wealth*(1+drift*dt-weight*sigma*sqrt(dt));
    if(up<=0||down<=0)continue;
    double value=(log(up)+log(down))/2;
    if(value>best){best=value;bestWeight=weight;}
}
cout<<"HJB grid control "<<bestWeight<<" value "<<best<<"
";
return 0;
}

